package io.github.chankamman_dev.stardewds;
import java.io.*;import java.nio.file.*;import java.security.*;import java.util.*;import java.util.zip.*;
public final class AssetPackStoreTest {
 static int checks;static void check(boolean v,String label){if(!v)throw new AssertionError(label);checks++;}
 static byte[] pack(String extra,boolean badHash,boolean missing)throws Exception{Map<String,byte[]> data=new LinkedHashMap<>();for(String name:new String[]{"offline.json","art/objects.png","art/frame-main.png","art/icon-bag.png"})data.put(name,new byte[]{1,2,3});if(extra!=null)data.put(extra,new byte[]{7});StringBuilder m=new StringBuilder("stardew-thor.assets.v1\n");for(Map.Entry<String,byte[]> e:data.entrySet()){StringBuilder h=new StringBuilder();for(byte v:MessageDigest.getInstance("SHA-256").digest(e.getValue()))h.append(String.format("%02x",v&255));m.append(badHash?String.join("",Collections.nCopies(64,"0")):h).append('\t').append(e.getValue().length).append('\t').append(e.getKey()).append('\n');}ByteArrayOutputStream out=new ByteArrayOutputStream();try(ZipOutputStream zip=new ZipOutputStream(out)){zip.putNextEntry(new ZipEntry("assets.tsv"));zip.write(m.toString().getBytes("UTF-8"));zip.closeEntry();for(Map.Entry<String,byte[]> e:data.entrySet()){if(missing&&e.getKey().equals("offline.json"))continue;zip.putNextEntry(new ZipEntry(e.getKey()));zip.write(e.getValue());zip.closeEntry();}}return out.toByteArray();}
 static void reject(AssetPackStore store,byte[] pack,String label)throws Exception{try{store.install(new ByteArrayInputStream(pack));throw new AssertionError(label);}catch(IOException expected){checks++;}check(store.ready(),label+" preserves active pack");try(InputStream in=store.open("offline.json")){check(in.read()==1,label+" preserves content");}}
 static String reason(AssetPackStore store,byte[] pack)throws Exception{try{store.install(new ByteArrayInputStream(pack));}catch(Exception e){return AssetPackStore.reason(e);}throw new AssertionError("accepted");}
 public static void main(String[] args)throws Exception{Path root=Paths.get(args[0]);AssetPackStore store=new AssetPackStore(root.toFile());check(!store.ready(),"fresh storage");check(store.install(new ByteArrayInputStream(pack(null,false,false)))==4,"valid import");check(new AssetPackStore(root.toFile()).ready(),"restart persists import");reject(store,pack("../escape.png",false,false),"traversal");reject(store,pack("app.js",false,false),"executable replacement");reject(store,pack("art/x.js",false,false),"nested executable");reject(store,pack(null,true,false),"bad hash");reject(store,pack(null,false,true),"missing member");check(store.install(new ByteArrayInputStream(pack("audio/cancel.wav",false,false)))==5,"replacement pack");check(Files.list(root).filter(p->p.getFileName().toString().startsWith("pack-")).count()==1,"failed and obsolete packs removed");check(!AssetPackStore.allowed("art/../../key.json"),"private-file path rejected");
  // Failures reach the page as a reason it can explain (first-run guide and Settings).
  check(reason(store,"not a zip at all".getBytes("UTF-8")).equals("format"),"plain file is not a pack");check(reason(store,pack(null,false,true)).equals("incomplete"),"missing member is incomplete");
  check(reason(store,pack(null,true,false)).equals("damaged"),"bad hash is damaged");check(reason(store,pack("app.js",false,false)).equals("format"),"executable entry is not a pack");
  check(AssetPackStore.reason(new IOException("Asset too large")).equals("size"),"oversize");check(AssetPackStore.reason(new java.util.zip.ZipException("invalid LOC header")).equals("read"),"corrupt zip is unreadable");
  long[] summary=store.summary();check(summary!=null&&summary[0]==5,"summary counts the active pack's files");check(new AssetPackStore(root.resolve("empty").toFile()).summary()==null,"no pack, no summary");if(args.length>1){try(InputStream in=new FileInputStream(args[1])){check(store.install(in)>2000,"full owned-game pack");}check(new AssetPackStore(root.toFile()).ready(),"full pack survives restart");}System.out.println("PASS asset pack: "+checks+" checks");}
}
